export const getOneEquipSetById = async (id_equip_set: number): Promise<IEquipSet | null> => {
  const res = await get<IEquipSetDto, { id: number }>('/ajax/users/equip/equip_set_one.php', {
    id: id_equip_set,
  }).then(handleApiError);

  if (res.noSet) return null;

  return mapEquipSetToFront(res);
};

export const getOneEquipSetByHikingId = async (id_hiking: number): Promise<IEquipSet | null> => {
  const res = await get<IEquipSetDto, { id_hiking: number }>(
    '/ajax/users/equip/equip_set_one.php',
    {
      id_hiking,
    },
  ).then(handleApiError);

  if (res.noSet) return null;

  return mapEquipSetToFront(res);
};

