export interface IGetEquipCriteria {
  is_group?: boolean;
  is_musthave?: boolean;
  is_archive?: boolean;
  id_parent?: number;
  id_category?: number;
}

export const getEquipItems = async (data: IGetEquipCriteria = {}): Promise<IEquip[]> => {
  const res = await get('/ajax/users/equip/equip_list.php', data).then<IEquipDTO[]>(handleApiError);
  return res.map(mapEquipToFront);
};

export const addEquip = async (equip: IEquip): Promise<number | undefined> => {
  const res = await post<{ success?: boolean; id?: number }, IHikingEquipAddOrUpdateDTO>(
    '/ajax/users/equip/equip_add.php',
    mapEquipToAddUpdateDTO(equip),
  ).then(handleApiError);
  return res?.id;
};
