export async function saveHikingCommonEquip(
  id_hiking: number,
  hikingEquipItem: IHikingEquip,
): Promise<number> {
  const { id, name, user, weight, value, isConfirm, photo } = hikingEquipItem;
  const res = await post('/ajax/hiking/equip_save.php', {
    id_hiking,
    id,
    name,
    id_user: user ? user.id : null,
    weight,
    value,
    is_confirm: isConfirm ? 1 : 0,
    photo,
  }).then(handleApiError);
  return +res.id;
}

export async function deleteHikingCommonEquip(id_hiking: number, id: number): Promise<boolean> {
  const res = await post('/ajax/hiking/equip_del.php', { id, id_hiking }).then(handleApiError);
  return !!res?.success;
}

export async function confirmHikingCommonEquipToggle(
  id_hiking: number,
  hikingEquip: IHikingEquip,
): Promise<boolean> {
  await post('/ajax/hiking/equip_confirm.php', {
    id: hikingEquip.id,
    id_equip: hikingEquip.id_equip,
    id_hiking,
    confirm: hikingEquip.isConfirm ? 0 : 1,
  }).then(handleApiError);
  return !hikingEquip.isConfirm;
}

